<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/backup_step18.php';
try{$pdo=business_db();backup_step18_ensure($pdo);$ctx=backup_step18_context($pdo);$orgId=(int)$ctx['organization_id'];$id=(int)($_GET['id']??0);$r=backup_step18_record($pdo,$orgId,$id);$path=backup_step18_resolve_path((string)$r['storage_path']);if(!is_file($path))throw new RuntimeException('Backup file is no longer available on this server.');$actual=hash_file('sha256',$path);if(!hash_equals((string)$r['file_sha256'],$actual))throw new RuntimeException('Backup file integrity check failed; download was blocked.');$name=preg_replace('/[^A-Za-z0-9._-]/','_',(string)$r['backup_code']).'.hwcbak';header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($path));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store, max-age=0');readfile($path);exit;}catch(Throwable $e){http_response_code(404);header('Content-Type: text/plain; charset=utf-8');echo 'Backup download unavailable: '.$e->getMessage();}